package org.springframework.samples.petclinic.rest.controller;

import java.util.List;

/**
 * Signals that an owner request omitted or left blank one or more required fields.
 *
 * <p>Carries the names of the offending fields so the exception handler can report
 * them back to the client in the {@code errors} array of the error response.
 */
public class MissingOwnerFieldsException extends RuntimeException {

    private final List<String> missingFields;

    public MissingOwnerFieldsException(List<String> missingFields) {
        super("Missing or blank required fields: " + missingFields);
        this.missingFields = List.copyOf(missingFields);
    }

    public List<String> getMissingFields() {
        return missingFields;
    }
}

